-- Top 12 job families with average package. Columns: job, n, avg_sal
-- Job titles live in CODES_MASTER CODE_TYPE 250 (USER_CODE = STAFF_JOB_ID). GS_JOBS is empty at Al Faihaa.
SELECT * FROM (SELECT j.DESCRIPTION JOB, COUNT(*) N, ROUND(AVG(x.TOT)) AVG_SAL FROM (SELECT c.STAFF_ID, (SELECT MAX(t.STAFF_JOB_ID) FROM {P}PS_STAFF_INTERNAL_TRANSFERS t WHERE t.STAFF_ID=c.STAFF_ID AND t.CURRENT_JOB='Y') JB, (SELECT MAX(s.BASIC_SALARY) FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL) + NVL((SELECT SUM(d.SALARY_ITEM_AMOUNT) FROM {P}PR_STAFF_DEFAULT_SALARY_D d WHERE d.STAFF_ID=c.STAFF_ID AND d.DATE_START=(SELECT MAX(s2.DATE_START) FROM {P}PR_STAFF_DEFAULT_SALARY_M s2 WHERE s2.STAFF_ID=c.STAFF_ID AND s2.DATE_END IS NULL)),0) TOT FROM {P}PS_STAFF_CONTRACT c WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y') x LEFT JOIN (SELECT USER_CODE, MAX(DESCRIPTION) DESCRIPTION FROM {P}CODES_MASTER WHERE CODE_TYPE=250 GROUP BY USER_CODE) j ON j.USER_CODE=x.JB GROUP BY j.DESCRIPTION ORDER BY 2 DESC) WHERE ROWNUM<=12
